// Hand-written for skew-draco-sys (NOT generated by CMake).
//
// Content: the feature list that Draco 1.5.7's CMake configuration writes
// for a default non-Emscripten build (cmake/draco_options.cmake,
// draco_set_optional_features(): point cloud + mesh compression, normal
// encoding, standard + predictive edgebreaker, backwards compatibility, and
// attribute index/value deduplication), in the same order. The transcoder,
// Unity and Maya features are off, as in the default build.
//
// The point-cloud KD-tree decode path used by the experiment does not depend
// on the mesh features; they are kept so that the decoder accepts exactly
// what a default Draco 1.5.7 library (the one DracoPy 2.0.0 bundles) accepts.

#ifndef DRACO_FEATURES_H_
#define DRACO_FEATURES_H_

#define DRACO_POINT_CLOUD_COMPRESSION_SUPPORTED
#define DRACO_MESH_COMPRESSION_SUPPORTED
#define DRACO_NORMAL_ENCODING_SUPPORTED
#define DRACO_STANDARD_EDGEBREAKER_SUPPORTED
#define DRACO_PREDICTIVE_EDGEBREAKER_SUPPORTED
#define DRACO_BACKWARDS_COMPATIBILITY_SUPPORTED
#define DRACO_ATTRIBUTE_INDICES_DEDUPLICATION_SUPPORTED
#define DRACO_ATTRIBUTE_VALUES_DEDUPLICATION_SUPPORTED

#endif  // DRACO_FEATURES_H_
